'use strict';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const euro=n=>new Intl.NumberFormat('de-DE',{style:'currency',currency:'EUR'}).format(n/100), amount=n=>n===null?'':(n/100).toFixed(2), date=()=>new Date().toLocaleDateString('sv-SE'), uid=()=>crypto.randomUUID();
let state=null,key=null,salt=null,db=null,view='orders',selected=null,persistChain=Promise.resolve(),lastActivity=Date.now(),saving=false,storageError=false,lockWarned=false;
const statuses=['Anfrage','Angebot','Freigegeben','Druckdaten prüfen','Bereit für Druck','Gedruckt','Transferieren','Fertig','Versendet / abgeholt','Storniert'];
function toast(t){const status=$('#modalStatus');if($('#modal')?.open&&status){status.textContent=t;status.hidden=false;status.scrollIntoView?.({block:'nearest'});}$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,6500);}
function fail(e){console.error(e);toast(e.message||String(e));}
function act(fn){return async e=>{try{await fn(e)}catch(x){fail(x)}};}
function bind(id,event,fn){const e=$(id);if(e)e.addEventListener(event,act(fn));}
function button(id,text,cls=''){return `<button id="${id}" class="${cls}" type="button">${text}</button>`;}
function input(name,label,value='',type='text',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function textfield(name,label,value=''){return `<label>${label}<textarea name="${name}">${esc(value)}</textarea></label>`;}
function select(name,label,opts,value){return `<label>${label}<select name="${name}">${opts.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`}).join('')}</select></label>`;}
function formData(f){return Object.fromEntries(new FormData(f));}
function modal(html,fn){$('#modal').innerHTML=`<div class="row spread"><h2>${html.title}</h2>${button('closeModal','Schließen')}</div><p id="modalStatus" class="notice" role="alert" hidden></p>${html.body}`;$('#modal').showModal();bind('#closeModal','click',()=>$('#modal').close());if(fn)fn();}
function b64(a){let s='';for(let i=0;i<a.length;i+=32768)s+=String.fromCharCode(...a.slice(i,i+32768));return btoa(s);}
function un64(s){return Uint8Array.from(atob(s),c=>c.charCodeAt(0));}
async function derive(pass,s){const k=await crypto.subtle.importKey('raw',new TextEncoder().encode(pass),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt:s,iterations:600000,hash:'SHA-256'},k,{name:'AES-GCM',length:256},false,['encrypt','decrypt']);}
async function seal(s,k=key,sa=salt){const iv=crypto.getRandomValues(new Uint8Array(12));const data=await crypto.subtle.encrypt({name:'AES-GCM',iv},k,new TextEncoder().encode(JSON.stringify(s)));return {format:'RehaTexstyleVault',version:1,kdf:'PBKDF2-SHA256',iterations:600000,salt:b64(sa),iv:b64(iv),data:b64(new Uint8Array(data))};}
async function unlockEnvelope(env,pass){if(env?.format!=='RehaTexstyleVault'||env.version!==1||env.iterations!==600000)throw Error('Kein unterstütztes RehaTexstyle-Projekt.');const sa=un64(env.salt);if(sa.length!==16||un64(env.iv).length!==12)throw Error('Beschädigte Projektdatei.');const k=await derive(pass,sa);let raw;try{raw=await crypto.subtle.decrypt({name:'AES-GCM',iv:un64(env.iv)},k,un64(env.data));}catch{throw Error('Passwort falsch oder Datei beschädigt.');}return {state:Core.validState(JSON.parse(new TextDecoder().decode(raw))),key:k,salt:sa};}
async function openSealed(env,k=key){const raw=await crypto.subtle.decrypt({name:'AES-GCM',iv:un64(env.iv)},k,un64(env.data));return JSON.parse(new TextDecoder().decode(raw));}
async function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('RehaTexstylePilot',2);r.onupgradeneeded=()=>{for(const n of ['vault','images','device'])if(!r.result.objectStoreNames.contains(n))r.result.createObjectStore(n);};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function dbGet(){return new Promise((resolve,reject)=>{const r=db.transaction('vault').objectStore('vault').get('active');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function dbPut(env){return new Promise((resolve,reject)=>{const t=db.transaction('vault','readwrite');t.objectStore('vault').put(env,'active');t.oncomplete=resolve;t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error||Error('Speichern abgebrochen'));});}
function save(){if(!state)return Promise.resolve();for(const o of state.orders){try{syncApplication(o);delete o.syncError;}catch(e){o.syncError=e.message;}}if(order()?.syncError)toast('Kalkulation dieses Auftrags unvollständig: '+order().syncError);state.rev++;state.changed=new Date().toISOString();const snapshot=structuredClone(state),k=key,sa=salt;saving=true;$('#saveState').textContent='Speichern …';persistChain=persistChain.catch(()=>{}).then(async()=>{await dbPut(await seal(snapshot,k,sa));storageError=false;$('#saveState').textContent='Lokal verschlüsselt gespeichert';}).catch(e=>{storageError=true;$('#saveState').textContent='Nicht gespeichert – Sicherung erstellen!';throw Error('Lokales Speichern fehlgeschlagen: '+e.message);}).finally(()=>saving=false);return persistChain;}
async function download(data,name,type){const chosen=prompt('Dateiname vor dem Speichern:',name);if(!chosen)return false;const filename=chosen.replace(/[\\/:*?"<>|]/g,'_');const blob=new Blob([data],{type});if(window.showSaveFilePicker){try{const h=await window.showSaveFilePicker({suggestedName:filename});const w=await h.createWritable();await w.write(blob);await w.close();toast('Datei gespeichert.');return true;}catch(e){if(e.name==='AbortError')return false;if(e.name!=='SecurityError')throw e;}}const a=document.createElement('a'),u=URL.createObjectURL(blob);a.href=u;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(u),30000);toast('Download angefordert. Den Zielordner bestimmt dieser Browser.');return true;}
async function backup(){await persistChain.catch(()=>{});const {images,missing}=await backupImages();if(missing&&!confirm(`${missing} Bild(er) fehlen im lokalen Speicher und sind nicht in der Sicherung. Trotzdem sichern?`))return false;const done=await download(JSON.stringify({format:'RehaTexstyleBackup',version:2,vault:await seal(state),images}),`RehaTexstyle_${date()}_Stand_${state.rev}.rtx`,'application/json');return done;}
function newState(){return {version:1,id:uid(),rev:0,changed:'',customers:[],orders:[],catalog:[],docs:[],settings:{company:'',address:'',taxid:'',email:'',iban:'',bank:'',footer:'',prefix:'RT',paymentDays:14},counters:{order:0,Angebot:0,Lieferschein:0,Rechnung:0,Storno:0}};}
async function gate(){const existing=await dbGet();$('#nav').hidden=true;$('#saveState').textContent='Gesperrt';$('#app').innerHTML=`<section class="card" style="max-width:640px;margin:30px auto"><h1>${existing?'Arbeitsbereich entsperren':'Offline-Arbeitsbereich einrichten'}</h1><p>Kunden, Motive und Aufträge bleiben lokal. Passwortgeschützte Projektdateien dienen als Sicherung und zum manuellen Übertragen.</p><form id="gateForm">${input('pass','Passwort','', 'password','required minlength="12" autocomplete="current-password"')}${existing?'':input('repeat','Passwort wiederholen','','password','required minlength="12"')}<p class="sub">Mindestens 12 Zeichen. Ohne Passwort kann die Sicherung nicht wiederhergestellt werden. Browserdaten sind kein Ersatz für eine eigene Sicherungsdatei.</p><button class="primary">${existing?'Entsperren':'Arbeitsbereich erstellen'}</button></form><hr><label>Vorhandene verschlüsselte Projektdatei öffnen<input id="restoreGate" type="file" accept=".rtx,application/json"></label><div class="notice">Pilot für Funktionstests. Noch keine zertifizierte Archivierung oder vollständige E-Rechnungsfunktion. Bitte zunächst mit Testdaten arbeiten.</div></section>`;
bind('#gateForm','submit',async e=>{e.preventDefault();const f=formData(e.target);if(!existing&&f.pass!==f.repeat)throw Error('Passwörter stimmen nicht überein.');e.target.querySelector('button').disabled=true;try{if(existing){const r=await unlockEnvelope(existing,f.pass);state=r.state;key=r.key;salt=r.salt;}else{salt=crypto.getRandomValues(new Uint8Array(16));key=await derive(f.pass,salt);await clearImageStore();await idbDelete('vault','draft');state=newState();await save();}await afterUnlock();}finally{if(!state)e.target.querySelector('button').disabled=false;}});
bind('#restoreGate','change',e=>restore(e.target.files[0]));}
async function restore(file){if(!file)return;if(file.size>300*1024*1024)throw Error('Projektdatei größer als 300 MB.');const json=JSON.parse(await file.text());const v2=json?.format==='RehaTexstyleBackup';if(v2&&json.version!==2)throw Error('Unbekannte Sicherungsversion. Neuere App verwenden.');const pass=await askPassword('Passwort dieser Projektdatei');if(pass===null)return;const r=await unlockEnvelope(v2?json.vault:json,pass);const images=v2?await readBackupImages(json.images,r.key):[];let old=state;const active=await dbGet();if(!old&&active){const p=await askPassword('Zum Vergleichen: Passwort des vorhandenen Arbeitsbereichs');if(p===null)return;old=(await unlockEnvelope(active,p)).state;}
if(old&&old.id===r.state.id&&r.state.rev<old.rev)throw Error('Die Datei ist älter als der vorhandene Stand. Import wurde verhindert.');if(old&&!confirm('Diese vollständige Datei ersetzt den lokalen Arbeitsbereich. Keine Zusammenführung. Vorher eine Sicherung auf dem bisherigen Gerät aufbewahren. Fortfahren?'))return;
await dbPut(await seal(r.state,r.key,r.salt));await idb('images','readwrite',s=>{s.clear();for(const [h,rec] of images)s.put(rec,h);});clearImageCache();await idbDelete('vault','draft');state=r.state;key=r.key;salt=r.salt;selected=null;view='orders';await afterUnlock();toast('Projekt geöffnet. Nur auf einem Gerät weiterbearbeiten.');}
// Nach dem Entsperren: Altbilder auslagern, verwaiste Bilder entfernen, Bilder laden, Gerät prüfen.
async function afterUnlock(){await loadDevice();if(await migrateImages())await save();try{await collectGarbageImages();}catch(e){console.error(e);}await loadImages();await requestPersistentStorage();render();if(!deviceInfo.code)deviceDialog();else await offerDraft();}
function askPassword(text){return new Promise(resolve=>{const d=$('#passDialog');let done=false;const finish=v=>{if(done)return;done=true;d.close();d.innerHTML='';resolve(v);};d.innerHTML=`<form id="passForm"><h2>${esc(text)}</h2><label>Passwort<input name="pass" type="password" autocomplete="current-password" required></label><div class="row"><button class="primary">OK</button><button id="passCancel" type="button">Abbrechen</button></div></form>`;d.onclose=()=>finish(null);d.querySelector('#passForm').onsubmit=e=>{e.preventDefault();finish(e.target.elements.pass.value);};d.querySelector('#passCancel').onclick=()=>finish(null);d.showModal();d.querySelector('input').focus();});}
async function setDeviceCode(v){const code=String(v).trim().toUpperCase();if(!validDeviceCode(code))throw Error('Gerätekennung: 1 bis 6 Zeichen, nur A bis Z und 0 bis 9.');deviceInfo.code=code;await saveDevice();toast('Gerätekennung '+code+' gespeichert.');}
function deviceDialog(){modal({title:'Gerätekennung festlegen',body:`<p>Jedes Gerät vergibt eigene Auftrags- und Dokumentnummern, zum Beispiel <strong>${esc(state.settings.prefix)}-PC1-RE-2026-00001</strong>. So entstehen auf zwei Geräten nie dieselben Nummern.</p><form id="deviceForm">${input('code','Gerätekennung (1 bis 6 Zeichen, A bis Z und 0 bis 9)',deviceInfo.code,'text','required pattern="[A-Za-z0-9]{1,6}" autocapitalize="characters"')}<p class="sub">Jede Kennung nur an einem Gerät verwenden, etwa PC1, PC2, TAB1. Vergebene Kennungen im Betrieb notieren. Die Kennung bleibt auf diesem Gerät, auch wenn ein anderer Arbeitsbereich importiert wird.</p><button class="primary">Speichern</button></form>`},()=>bind('#deviceForm','submit',async e=>{e.preventDefault();await setDeviceCode(formData(e.target).code);$('#modal').close();render();}));}
// Entwürfe: Beim automatischen Sperren werden ungespeicherte Formulareingaben verschlüsselt aufbewahrt.
const draftTitles={customerForm:'Kunde',orderForm:'Auftragsdaten',settingsForm:'Einstellungen',lineForm:'Position',placementForm:'Motivplatzierung',variantForm:'Katalogartikel'};
function labelText(e){const l=e.closest('label');const t=l?Array.from(l.childNodes).filter(n=>n.nodeType===3).map(n=>n.textContent).join(' ').trim():'';return t||e.name;}
function dirtyForms(){return Array.from(document.querySelectorAll('form[data-dirty]')).filter(f=>f.id&&(!f.closest('dialog')||f.closest('dialog').open));}
async function stashDraft(){const forms=dirtyForms().map(f=>({id:f.id,record:f.dataset.id||'',fields:Array.from(f.elements).filter(e=>e.name&&!['file','password','submit','button','range'].includes(e.type)).map(e=>({name:e.name,label:labelText(e),value:e.type==='checkbox'?e.checked:e.value}))})).filter(f=>f.fields.length);if(forms.length)await idbPut('vault','draft',await seal({view,selected,forms}));}
async function offerDraft(){let draft;try{const env=await idbGet('vault','draft');if(!env)return;draft=await openSealed(env);}catch{await idbDelete('vault','draft');return;}const restorable=f=>['customerForm','orderForm','settingsForm'].includes(f.id);
const keep=async f=>{draft.forms=draft.forms.filter(x=>x!==f);if(draft.forms.length)await idbPut('vault','draft',await seal(draft));else await idbDelete('vault','draft');};
modal({title:'Eingaben vor der automatischen Sperre',body:`<p>Diese Eingaben waren beim automatischen Sperren noch nicht gespeichert.</p>${draft.forms.map((f,i)=>`<section class="card"><h3>${esc(draftTitles[f.id]||'Formular')}</h3><table>${f.fields.filter(x=>x.value!==''&&x.value!==false).map(x=>`<tr><th>${esc(x.label)}</th><td>${esc(x.value===true?'ja':x.value)}</td></tr>`).join('')}</table>${restorable(f)?button('restoreDraft'+i,'Formular mit diesen Eingaben öffnen','primary'):'<p class="sub">Dieses Formular lässt sich nicht automatisch wieder öffnen. Angaben bitte von Hand übertragen.</p>'}</section>`).join('')}${button('discardDraft','Entwurf verwerfen','danger')}`},()=>{draft.forms.forEach((f,i)=>bind('#restoreDraft'+i,'click',async()=>{await keep(f);$('#modal').close();reopenForm(draft,f);}));bind('#discardDraft','click',async()=>{await idbDelete('vault','draft');$('#modal').close();});});}
function reopenForm(draft,f){if(f.id==='customerForm'){if(f.record&&!customer(f.record))throw Error('Der Kunde existiert nicht mehr.');editCustomer(f.record||undefined);}else{view=draft.view;selected=draft.selected;if(f.id==='orderForm'&&!order())throw Error('Der Auftrag existiert nicht mehr.');render();}const form=document.getElementById(f.id);if(!form)return;for(const x of f.fields){const e=form.elements[x.name];if(!e||e instanceof RadioNodeList)continue;if(e.type==='checkbox')e.checked=x.value;else e.value=x.value;}form.dataset.dirty='1';toast('Eingaben wiederhergestellt. Bitte prüfen und speichern.');}
async function lock(auto=false){await persistChain.catch(()=>{});if(!auto&&storageError&&!confirm('Die letzten Änderungen konnten nicht gespeichert werden. Sie gehen beim Sperren verloren. Vorher über „Sicherung / Übergabe“ sichern. Trotzdem sperren?'))return;if(auto)await stashDraft().catch(e=>console.error(e));state=null;key=null;salt=null;selected=null;clearImageCache();$('#modal').close();$('#modal').innerHTML='';$('#printArea').innerHTML='';await gate();}
function render(){if(!state)return;lastActivity=Date.now();$('#nav').hidden=false;$('#nav').innerHTML=[['orders','Aufträge'],['customers','Kunden'],['catalog','Artikel / Excel'],['documents','Dokumente'],['settings','Einstellungen']].map(([k,t])=>button('nav_'+k,t,view===k?'active':'')).join('')+button('backup','Sicherung / Übergabe')+button('lock','Sperren');for(const k of ['orders','customers','catalog','documents','settings'])bind('#nav_'+k,'click',()=>{view=k;render();});bind('#backup','click',backup);bind('#lock','click',()=>lock(false));({orders:ordersPage,customers:customersPage,catalog:catalogPage,documents:documentsPage,settings:settingsPage})[view]();}
function customer(id){return state.customers.find(c=>c.id===id);}
function order(){return state.orders.find(o=>o.id===selected);}
function customersPage(){const app=$('#app');app.innerHTML=`<div class="row spread"><h1>Kunden</h1>${button('newCustomer','Kunde anlegen','primary')}</div><section class="card"><label>Suchen<input id="customerSearch" placeholder="Name, Firma oder Kundennummer"></label><div id="customerList"></div></section>`;const list=()=>{const q=$('#customerSearch').value.toLowerCase();$('#customerList').innerHTML=`<table><thead><tr><th>Kunde</th><th>Kontakt</th><th>Aktion</th></tr></thead><tbody>${state.customers.filter(c=>(c.name+c.number+c.email).toLowerCase().includes(q)).map(c=>`<tr><td><strong>${esc(c.name)}</strong><br>${esc(c.number)}</td><td>${esc(c.email)}<br>${esc(c.phone)}</td><td><button data-customer="${c.id}">Bearbeiten</button></td></tr>`).join('')}</tbody></table>`;document.querySelectorAll('[data-customer]').forEach(b=>b.onclick=()=>editCustomer(b.dataset.customer));};bind('#customerSearch','input',list);bind('#newCustomer','click',()=>editCustomer());list();}
function editCustomer(id){const c=customer(id)||{id:uid(),name:'',number:'',email:'',phone:'',address:'',delivery:'',notes:''};modal({title:id?'Kunde bearbeiten':'Kunde anlegen',body:`<form id="customerForm" data-id="${esc(id||'')}"><div class="grid">${input('name','Name / Firma',c.name,'text','required')}${input('number','Kundennummer',c.number)}${input('email','E-Mail',c.email,'email')}${input('phone','Telefon',c.phone)}</div>${textfield('address','Rechnungsanschrift: Straße, PLZ, Ort, Land',c.address)}${textfield('delivery','Abweichende Lieferanschrift (optional)',c.delivery)}${textfield('notes','Interne Notiz',c.notes)}<div class="row"><button class="primary">Speichern</button>${id?button('deleteCustomer','Kunde löschen','danger'):''}</div></form>`},()=>{bind('#customerForm','submit',async e=>{e.preventDefault();Object.assign(c,formData(e.target));if(!id)state.customers.push(c);await save();$('#modal').close();render();});bind('#deleteCustomer','click',async()=>{if(state.orders.some(o=>o.customerId===id)||state.docs.some(d=>d.customer.id===id))throw Error('Kunde wird in Aufträgen oder Dokumenten verwendet. Nicht pauschal löschbar.');if(!confirm('Kunde endgültig aus diesem Arbeitsbereich löschen? Exporte und Sicherungen bleiben unverändert.'))return;state.customers=state.customers.filter(x=>x.id!==id);await save();$('#modal').close();render();});});}
function ordersPage(){if(selected&&order()){orderPage();return;}$('#app').innerHTML=`<div class="row spread"><h1>Aufträge</h1>${button('newOrder','Auftrag anlegen','primary')}</div><div class="stats"><div class="stat">Aufträge<strong>${state.orders.length}</strong></div><div class="stat">Kunden<strong>${state.customers.length}</strong></div><div class="stat">Katalog-Preiszeilen<strong>${state.catalog.length}</strong></div></div><section class="card" style="margin-top:20px"><div class="grid"><label>Suche<input id="orderSearch" placeholder="Kunde, BA-Nummer, Auftrag"></label>${select('filterStatus','Status',['Alle',...statuses],'Alle')}</div><div id="orderList"></div></section>`;const list=()=>{const q=$('#orderSearch').value.toLowerCase(),st=$('[name=filterStatus]').value;$('#orderList').innerHTML=`<div class="tablewrap"><table><thead><tr><th>Auftrag / BA</th><th>Kunde</th><th>Termin</th><th>Status</th><th></th></tr></thead><tbody>${state.orders.filter(o=>(st==='Alle'||o.status===st)&&(o.number+o.ba+(customer(o.customerId)?.name||'')).toLowerCase().includes(q)).map(o=>`<tr><td>${esc(o.number)}<br><span class="sub">${esc(o.ba)}</span></td><td>${esc(customer(o.customerId)?.name||'Kein Kunde')}</td><td>${esc(o.due||'Offen')}</td><td><span class="badge">${esc(o.status)}</span></td><td><button data-order="${o.id}">Öffnen</button></td></tr>`).join('')}</tbody></table></div>`;document.querySelectorAll('[data-order]').forEach(b=>b.onclick=()=>{selected=b.dataset.order;render();});};bind('#orderSearch','input',list);bind('[name=filterStatus]','change',list);bind('#newOrder','click',async()=>{const num=nextNumber('order');const o={id:uid(),number:num.number,customerId:'',ba:'',due:'',serviceDate:'',status:'Anfrage',notes:'',salesVersion:2,salesTax:7,lines:[],placements:[],garment:'T-Shirt',color:'#f1f1ec'};state.orders.unshift(o);selected=o.id;await num.commit();await save();render();});list();}
function orderPage(){const o=order();let totals;try{totals=Core.total(o.lines)}catch{}$('#app').innerHTML=`<div class="row spread"><div>${button('backOrders','← Aufträge')}<h1 style="margin-top:15px">${esc(o.number)}</h1></div><span class="badge">${esc(o.status)}</span></div><section class="card"><h2>Auftragsdaten</h2><form id="orderForm" data-id="${esc(o.id)}"><div class="grid">${select('customerId','Kunde',[['','Bitte auswählen'],...state.customers.map(c=>[c.id,c.name])],o.customerId)}${input('ba','BA-Nummer',o.ba)}${input('due','Termin',o.due,'date')}${input('serviceDate','Liefer-/Leistungsdatum',o.serviceDate,'date')}${select('status','Status',statuses,o.status)}${select('garment','Textilvorschau',['T-Shirt','Hoodie','Jacke'],o.garment)}</div>${textfield('notes','Interne Werkstattnotiz',o.notes)}<button class="primary">Auftragsdaten speichern</button></form></section><section class="card"><div class="row spread"><h2>Textilien und Leistungen</h2><div>${button('addCatalog','Aus HAKRO-Katalog')}${button('addLine','Artikel hinzufügen','primary')}${button('addFreeLine','Freie Position (leeres Formular)')}${button('application','Transfers aufbringen')}${button('commercial','Druckpreise / Bruttokalkulation')}</div></div><p class="sub">VK werden brutto angezeigt. EK bleiben netto und intern. VK folgt bei Katalogpositionen der Industriestaffel oder wird manuell festgelegt. Aufbringen wird im Automatikmodus aus Textilmengen und Transfers je Textil berechnet; zugeordnete Motive haben Vorrang.</p><div class="tablewrap"><table><thead><tr><th>Artikel / Leistung</th><th>Variante</th><th>Menge</th><th>EK intern</th><th>Stückpreis brutto</th><th>MwSt.</th><th></th></tr></thead><tbody>${o.lines.map(l=>`<tr><td>${esc(l.description)}<br><span class="sub">${esc(l.maker)} ${esc(l.model)}</span></td><td>${esc(l.color)} / ${esc(l.size)}</td><td>${l.qty}${l.unit==='lfm'?' lfm':''}</td><td>${euro(l.ek)}<br><span class="sub">${l.manualEk?'manuell':l.prices?'Staffel '+l.tier+'+':'manuell'}</span></td><td>${l.vk===null?(l.salesGenerated?'Preis auf Anfrage':'VK offen'):euro(Sales.gross(l))}<br><span class="sub">${l.salesGenerated?(l.kind==='application'?(o.pressManualPrice==null?'Bruttostaffel':'Manueller Sonderpreis'):'Transferkalkulation'):l.manualVk===false?'Industrie '+(l.vkTier===null?'ohne passende Staffel':'ab '+l.vkTier):'manuell'}</span></td><td>${l.tax===null?'Auswählen':l.tax+' %'}</td><td><button data-line="${l.id}">Bearbeiten</button></td></tr>`).join('')}</tbody></table></div>${o.syncError?`<p class="notice">Kalkulation unvollständig: ${esc(o.syncError)}</p>`:''}${totals?`<div class="row" style="margin-top:20px"><span class="badge">Interner EK ${euro(totals.ek)}</span><strong>VK netto ${euro(totals.net)} · MwSt. ${euro(totals.tax)} · Brutto ${euro(totals.gross)}</strong></div>`:'<p class="notice">Eigene Verkaufspreise und Steuersätze aller Positionen festlegen, bevor Kundendokumente erstellt werden.</p>'}</section><section class="card"><div class="row spread"><h2>Transferplatzierung</h2>${button('addPlacement','Motiv platzieren','primary')}</div><div id="placements">${o.placements.map(p=>`<div class="row" style="border-top:1px solid #ddd;padding:14px 0"><img alt="Motiv" src="${esc(imgUrl(p.src))}" style="width:75px;height:65px;object-fit:contain"><div><strong>${esc(p.name)}</strong><br>${esc(p.side)} · ${p.width} × ${p.height} mm<br><span class="sub">${esc(p.reference)} · x ${p.x} / y ${p.y} mm${p.needsReview?' · <strong>Übernommen: Platzierung am neuen Textil prüfen</strong>':''}</span></div><button data-placement="${p.id}">Bearbeiten</button></div>`).join('')||'<p>Noch keine Motive. PNG/JPG/WebP hochladen, Maße und Bezugspunkt festlegen.</p>'}</div></section><section class="card"><h2>Dokumente</h2><div class="row">${['Angebot','Lieferschein','Rechnung','Werkstattzettel','Bestellübersicht'].map(t=>`<button data-doc="${t}">${t}</button>`).join('')}</div><p class="sub">Bestellübersichten lösen keine HAKRO-Bestellung aus. Der Lieferschein enthält keine Preise. PDF über die Druckfunktion. Strukturierte E-Rechnung noch nicht enthalten.</p></section>`;
bind('#backOrders','click',()=>{selected=null;render();});bind('#orderForm','submit',async e=>{e.preventDefault();Object.assign(o,formData(e.target));await save();render();});bind('#addLine','click',()=>catalogPicker());bind('#addFreeLine','click',()=>editLine());bind('#application','click',serviceEditor);bind('#commercial','click',commercialEditor);bind('#addCatalog','click',()=>catalogPicker());bind('#addPlacement','click',()=>placementEditor());document.querySelectorAll('[data-line]').forEach(b=>b.onclick=()=>editLine(b.dataset.line));document.querySelectorAll('[data-placement]').forEach(b=>b.onclick=()=>placementEditor(b.dataset.placement));document.querySelectorAll('[data-doc]').forEach(b=>b.onclick=act(()=>createDocument(b.dataset.doc)));}
function editLine(id,seed){if(order().lines.find(l=>l.id===id)?.salesGenerated){commercialEditor();return;}if(order().lines.find(l=>l.id===id)?.kind==='application'){serviceEditor();return;}const o=order(),old=o.lines.find(l=>l.id===id),l=structuredClone(old||seed||{id:uid(),description:'',maker:'',model:'',color:'',size:'',qty:1,ek:0,vk:null,tax:7,priceBasis:'gross',manualEk:true});modal({title:id?'Position bearbeiten':'Position hinzufügen',body:`<form id="lineForm">${input('description','Artikel / Leistung',l.description,'text','required')}<div class="grid">${input('maker','Hersteller',l.maker)}${input('model','Modellnummer',l.model)}${input('color','Farbcode',l.color)}${input('size','Konkrete Größe',l.size)}${input('qty','Menge',l.qty,'number','min="1" max="100000" required step="1"')}${input('transfersPerItem','Transfers je Textil (0 = unveredelt; Motive haben Vorrang)',l.transfersPerItem??(l.maker==='HAKRO'?1:0),'number','min="0" max="100" step="1" required')}${input('ek','EK netto – nur intern',amount(l.ek),'text','required inputmode="decimal"')}${input('vk','VK brutto (€) – offen lassen, wenn noch nicht festgelegt',amount(Sales.gross(l)),'text','inputmode="decimal"')}${select('tax','Mehrwertsteuer',[['','Bitte auswählen'],[7,'7 %'],[19,'19 %']],l.tax??'')}</div>${designSourceSelect(o,l.id)}${button('useIndustry','Industriepreis übernehmen')}<p id="vkSource" class="sub">Ein offener VK kann später ergänzt werden. Angebot und Rechnung benötigen einen bestätigten VK.</p>${l.prices?'<p class="sub">Unveränderter EK folgt der Variantenstaffel. Bei Änderung des EK oder der Variante wird der Preis manuell festgehalten.</p>':''}<div class="row"><button class="primary">Speichern</button>${id?button('deleteLine','Position entfernen','danger'):''}</div></form>`},()=>{setupIndustryForm(l,o);bind('#lineForm','submit',async e=>{e.preventDefault();const f=formData(e.target);const ek=Core.cents(f.ek),vk=f.vk.trim()?Core.cents(f.vk):null,q=Core.qty(f.qty),tax=Number(f.tax);if(![7,19].includes(tax))throw Error('7 % oder 19 % bewusst auswählen.');const changedVariant=['maker','model','color','size'].some(k=>f[k]!==l[k]);if(!Number.isInteger(Number(f.transfersPerItem))||Number(f.transfersPerItem)<0||Number(f.transfersPerItem)>100)throw Error('Transfers je Textil prüfen.');const keepLegacy=l.priceBasis!=='gross'&&vk===Sales.gross(l)&&tax===l.tax;Object.assign(l,f,{priceBasis:keepLegacy?l.priceBasis:'gross',transfersPerItem:Number(f.transfersPerItem),qty:q,ek,vk:keepLegacy?l.vk:vk,tax,manualVk:l.manualVk!==false||changedVariant,manualEk:l.manualEk||ek!==l.ek||changedVariant});if(changedVariant){delete l.prices;delete l.industry;}if(old)o.lines[o.lines.indexOf(old)]=l;else o.lines.push(l);copyDesign(o,f.designSource,l.id);Core.reprice(o.lines);await save();$('#modal').close();render();});bind('#deleteLine','click',async()=>{if(!confirm('Position und zugehörige Motivplatzierungen aus diesem Auftrag entfernen?'))return;o.lines=o.lines.filter(x=>x.id!==id);o.placements=o.placements.filter(p=>p.lineId!==id);Core.reprice(o.lines);await save();$('#modal').close();render();});});}
function catalogPicker(){if(!state.catalog.length){toast('Zuerst unter Artikel / Excel die Händler-Einkaufspreisliste importieren.');return;}modal({title:'HAKRO-Artikel auswählen',body:`<label>Modellnummer oder Name<input id="pickSearch"></label><div id="pickResults"></div>`},()=>{const show=()=>{const q=$('#pickSearch').value.toLowerCase();const rows=state.catalog.filter(r=>(r.model+' '+r.name).toLowerCase().includes(q)).slice(0,35);$('#pickResults').innerHTML=rows.map(r=>`<div style="padding:10px;border-bottom:1px solid #ddd"><strong>${esc(r.model)} ${esc(r.name)}</strong><div class="sub">Größen ${esc(r.sizeText)} · Farben ${esc(r.colors.join(', '))}</div><button data-pick="${r.id}">Variante wählen</button></div>`).join('');document.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>pickVariant(state.catalog.find(r=>r.id===b.dataset.pick)));};bind('#pickSearch','input',show);show();});}
async function parseXlsx(file){if(file.size>15*1024*1024)throw Error('Excel-Datei größer als 15 MB.');const z=await JSZip.loadAsync(await file.arrayBuffer());const parse=s=>{const d=new DOMParser().parseFromString(s,'application/xml');if(d.querySelector('parsererror'))throw Error('Ungültiges Excel-XML.');return d;};const get=async n=>{const f=z.file(n);if(!f)throw Error('Excel-Bestandteil fehlt: '+n);const s=await f.async('string');if(s.length>30e6)throw Error('Excel-Inhalt zu groß.');return parse(s);};const ss=z.file('xl/sharedStrings.xml')?Array.from((await get('xl/sharedStrings.xml')).getElementsByTagName('si')).map(x=>Array.from(x.getElementsByTagName('t')).map(t=>t.textContent).join('')):[];const wb=await get('xl/workbook.xml'),rels=await get('xl/_rels/workbook.xml.rels');const sheet=Array.from(wb.getElementsByTagName('sheet')).find(s=>s.getAttribute('name')==='EU');if(!sheet)throw Error('Diese Version erwartet das HAKRO-Tabellenblatt EU. Andere Tabellenformate sind noch nicht unterstützt.');const rid=sheet.getAttribute('r:id'),rel=Array.from(rels.getElementsByTagName('Relationship')).find(x=>x.getAttribute('Id')===rid);if(!rel)throw Error('Tabellenblatt nicht gefunden.');let target=rel.getAttribute('Target');target=target.startsWith('/')?target.slice(1):'xl/'+target;const xml=await get(target),rows=[];for(const row of xml.getElementsByTagName('row')){const cells=[];for(const c of row.getElementsByTagName('c')){const letters=c.getAttribute('r').replace(/\d/g,'');let index=0;for(const a of letters)index=index*26+a.charCodeAt(0)-64;const v=c.getElementsByTagName('v')[0]?.textContent??'';const type=c.getAttribute('t');if(c.getElementsByTagName('f').length)throw Error('Formelzelle gefunden. Diese Pilotversion importiert nur feste Preiswerte.');cells[index-1]=type==='s'?ss[Number(v)]:type==='inlineStr'?Array.from(c.getElementsByTagName('t')).map(t=>t.textContent).join(''):v;}rows.push({row:Number(row.getAttribute('r')),cells});}
const head=rows.find(r=>String(r.cells[0]).trim()==='Modell'&&String(r.cells[1]).trim()==='Modellbezeichnung');if(!head)throw Error('HAKRO-Kopfzeile nicht erkannt.');const h=head.cells.map(x=>String(x??'').trim()),dealer=h[4]==='1+'&&h[8]==='UVP';if(!dealer&&h[4]!=='UVP')throw Error('Preis-Spalten nicht eindeutig erkannt.');const out=[],ignored=[],problems=[],rounded=[];const keys=new Set();for(const {row,cells:c} of rows.filter(x=>x.row>head.row)){if(!/^\d{3,4}$/.test(String(c[0]??''))){if(c.some(Boolean))ignored.push(row);continue;}const model=String(c[0]).padStart(4,'0'),name=String(c[1]??''),colorText=String(c[2]??''),sizeText=String(c[3]??'');const colors=colorText.split(';').map(c=>c.trim()).filter(Boolean);const sz=Core.sizes(sizeText);if(!name||!colors.length||colors.some(c=>!/^\d{3}$/.test(c))||!sz.length){problems.push({row,reason:'Farbe oder Größenbereich nicht automatisch zuordenbar',model,sizeText});continue;}try{const rawPrices=c.slice(4).map(v=>String(v??''));if(rawPrices.some(v=>v!==''&&Number.isFinite(Number(v))&&Math.abs(Number(v)*100-Math.round(Number(v)*100))>0.000001))rounded.push(row);const prices={};if(dealer)[1,10,100,500].forEach((n,i)=>prices[n]=Core.excelCents(c[4+i]));const uvp=Core.excelCents(c[dealer?8:4]);const industry={};[10,50,100,250,500].forEach((n,i)=>industry[n]=Core.excelCents(c[(dealer?9:5)+i]));const k=JSON.stringify([model,[...colors].sort(),sizeText]);if(keys.has(k))throw Error('Doppelte Preiszeile');keys.add(k);out.push({id:uid(),model,name,colors,sizes:sz,sizeText,prices,uvp,industry,source:file.name,row,rawPrices});}catch(e){problems.push({row,reason:e.message,model,sizeText});}}
return {rows:out,ignored,problems,rounded,dealer};}
function addCatalogRow(id){const r=state.catalog.find(x=>x.id===id);if(!r)throw Error('Artikel nicht gefunden.');if(!order()){if(!state.orders.length){toast('Zuerst unter Aufträge einen Auftrag anlegen.');return;}modal({title:'Zielauftrag auswählen',body:`<p>Für ${esc(r.model)} ${esc(r.name)} einen Auftrag wählen.</p>${state.orders.map(o=>`<p><button data-target-order="${esc(o.id)}">${esc(o.number)} · ${esc(customer(o.customerId)?.name||'Kunde offen')}</button></p>`).join('')}`},()=>{document.querySelectorAll('[data-target-order]').forEach(b=>b.onclick=()=>{selected=b.dataset.targetOrder;pickVariant(r);});});return;}pickVariant(r);}
function catalogPage(){$('#app').innerHTML=`<h1>Artikel und Excel-Preislisten</h1><section class="card"><h2>HAKRO importieren</h2><p>Die Händler-Einkaufspreisliste enthält EK-Staffeln. Die reine UVP-/Industriepreisliste liefert die Industriepreise für den Netto-VK. Die UVP bleibt eine Referenz; sie wird nicht automatisch als VK oder EK übernommen.</p><label>Excel-Datei auswählen<input id="excelFile" type="file" accept=".xlsx"></label><div id="importResult"></div></section><section class="card"><label>Katalog durchsuchen<input id="catalogSearch" placeholder="Modellnummer oder Modellbezeichnung"></label><div id="catalogList"></div></section>`;const show=()=>{const q=$('#catalogSearch').value.toLowerCase(),rs=state.catalog.filter(r=>(r.model+' '+r.name).toLowerCase().includes(q));$('#catalogList').innerHTML=`<p>${rs.length} Preiszeilen · Anzeige der ersten 60. ${selected&&order()?'Zielauftrag: '+esc(order().number):'Zum Übernehmen Auftrag wählen.'}</p><div class="tablewrap"><table><tr><th>Modell</th><th>Artikel</th><th>Größen</th><th>Farben</th><th>EK ab 1</th><th>Aktion</th></tr>${rs.slice(0,60).map(r=>`<tr><td>${esc(r.model)}</td><td>${esc(r.name)}</td><td>${esc(r.sizeText)}</td><td>${esc(r.colors.join(';'))}</td><td>${r.prices[1]===undefined?'EK fehlt · Händlerliste importieren oder manuell eingeben':euro(r.prices[1])}</td><td><button data-catalog-add="${esc(r.id)}">Zum Auftrag hinzufügen</button></td></tr>`).join('')}</table></div>`;document.querySelectorAll('[data-catalog-add]').forEach(b=>b.onclick=()=>addCatalogRow(b.dataset.catalogAdd));};bind('#catalogSearch','input',show);show();bind('#excelFile','change',async e=>{const f=e.target.files[0];if(!f)return;$('#importResult').textContent='Datei wird lokal geprüft …';const r=await parseXlsx(f);const keyOf=x=>JSON.stringify([x.model,[...x.colors].sort(),x.sizeText]);let added=0,updated=0;for(const x of r.rows){if(state.catalog.some(y=>keyOf(y)===keyOf(x)))updated++;else added++;}$('#importResult').innerHTML=`<div class="notice">${r.rows.length} gültige Preiszeilen · ${r.ignored.length} Hinweis-/Fußzeilen übersprungen · ${r.problems.length} Zeilen benötigen manuelle Prüfung.</div><p>Einzelpreise werden für diese Pilot-Kalkulation auf Cent gerundet. ${r.rounded.length} Zeilen enthalten zusätzliche Nachkommastellen; die Rohwerte bleiben im Katalog erhalten.</p><p>${added} neue / ${updated} vorhandene Preiszeilen. Bestehende Auftragspreise bleiben unverändert.</p>${r.problems.length?`<details open><summary>Prüfbedarf</summary><ul>${r.problems.map(x=>`<li>Zeile ${x.row}, Modell ${esc(x.model)}, ${esc(x.sizeText)}: ${esc(x.reason)}</li>`).join('')}</ul></details>`:''}${button('confirmImport','Gültige Preiszeilen übernehmen','primary')}`;bind('#confirmImport','click',async()=>{for(const x of r.rows){const i=state.catalog.findIndex(y=>keyOf(y)===keyOf(x));if(i<0)state.catalog.push(x);else{if(!r.dealer){x.prices=state.catalog[i].prices;x.source=state.catalog[i].source;x.row=state.catalog[i].row;}state.catalog[i]={...x,id:state.catalog[i].id};}}await save();render();toast(`${r.rows.length} Preiszeilen übernommen. ${r.problems.length} Zeilen nicht importiert.`);});});}
async function imageData(file){
if(!file)throw Error('Bitte eine Motivdatei auswählen.');
if(file.size>8*1024*1024)throw Error('Motiv größer als 8 MB. Bitte kleinere Vorschau verwenden.');
let bytes;try{bytes=new Uint8Array(await file.arrayBuffer());}catch{throw Error('Datei konnte nicht gelesen werden. Bitte lokal speichern und erneut auswählen.');}
const starts=a=>a.every((v,i)=>bytes[i]===v);
const mime=starts([137,80,78,71,13,10,26,10])?'image/png':starts([255,216,255])?'image/jpeg':starts([82,73,70,70])&&[87,69,66,80].every((v,i)=>bytes[i+8]===v)?'image/webp':null;
if(!mime)throw Error('Keine unterstützte Bilddatei. Bitte PNG, JPG oder WebP verwenden; PDF und SVG werden noch nicht unterstützt.');
return storeImageBytes(bytes,mime);
}
function garmentSvg(type,p={}){if(p.template?.startsWith('sketch-')&&!p.backgrounds?.[p.side])return textileSketch(p.template,p.side||'Vorderseite');const src=imgUrl(p.backgrounds?.[p.side])||(typeof GarmentPhotos!=='undefined'?GarmentPhotos[p.template]?.[p.side]:null);return src?`<image href="${esc(src)}" x="0" y="0" width="340" height="420" preserveAspectRatio="xMidYMid meet"/>`:'<rect width="340" height="420" fill="#fff"/><text x="170" y="210" text-anchor="middle" fill="#526873" font-size="14">Für diese Ansicht fehlt eine Vorlage.</text>';}
function makeDocument(type,o,c){syncApplication(o);return {id:uid(),type,number:'Entwurf',date:date(),customer:structuredClone(c),supplier:structuredClone(state.settings),order:{...structuredClone(o),placements:o.placements.map(p=>drawingPlacement(p,o.garment))},createdAt:new Date().toISOString(),frozen:false};}
function docHTML(d){const o=d.order,internal=['Werkstattzettel','Bestellübersicht'].includes(d.type),priced=['Angebot','Rechnung','Storno'].includes(d.type),s=d.supplier,c=d.customer;const sum=priced?Core.total(o.lines):null,sign=d.type==='Storno'?-1:1;const money=n=>euro(n*sign);const isGross=o.salesVersion===2||o.lines.some(l=>l.priceBasis==='gross');return `<article class="doc"><div class="watermark">Offline-Pilot · ${d.frozen?'gespeicherter Dokumentstand':'VORSCHAU'} · Rechnungs- und Archivabläufe noch nicht betrieblich abgenommen.</div><div class="row spread" style="margin-top:25px"><h1>${esc(d.type)}</h1><strong>${esc(s.company||'Absender noch eintragen')}</strong></div><div class="grid"><div><strong>${esc(c.name)}</strong><pre>${esc(d.type==='Lieferschein'&&c.delivery?c.delivery:c.address)}</pre></div><div><pre>${esc(s.address)}</pre>${s.taxid?`<div>Steuernummer / USt-IdNr.: ${esc(s.taxid)}</div>`:''}<div>${esc(s.email)}</div></div></div><p><strong>${esc(d.number)}</strong> · Datum ${esc(d.date)}<br>Auftrag ${esc(o.number)} · BA ${esc(o.ba||'–')}<br>Liefer-/Leistungsdatum: ${esc(o.serviceDate||'noch offen')}${d.original?'<br>Storno zu Rechnung '+esc(d.original):''}</p><table><thead><tr><th>Pos.</th><th>Artikel / Leistung</th><th>Menge</th>${priced?`<th>Einzelpreis ${isGross?'brutto':'netto'}</th><th>MwSt.</th><th>Gesamt ${isGross?'brutto':'netto'}</th>`:''}</tr></thead><tbody>${o.lines.map((l,i)=>`<tr><td>${i+1}</td><td><strong>${esc(l.description)}</strong><br>${esc([l.maker,l.model,l.color?'Farbe '+l.color:'',l.size?'Größe '+l.size:''].filter(Boolean).join(' · '))}</td><td>${l.qty}${l.unit==='lfm'?' lfm':''}</td>${priced?`<td>${money(isGross?Sales.gross(l):l.vk)}</td><td>${l.tax} %</td><td>${money(isGross?Sales.lineGross(l):l.vk*l.qty)}</td>`:''}</tr>`).join('')}</tbody></table>${sum?`<div class="totals"><p>Netto gesamt: <strong>${money(sum.net)}</strong></p>${[7,19].filter(t=>sum.groups[t]).map(t=>`<p>${t} % MwSt. auf ${money(sum.groups[t])}: ${money(sum.taxes[t])}</p>`).join('')}<p><strong>Gesamtbetrag: ${money(sum.gross)}</strong></p></div>`:''}${d.pendingPrint?.length?`<p><strong>Transferdruck noch offen</strong> für: ${esc(d.pendingPrint.join('; '))}. Der Druckpreis folgt nach Motivfreigabe. Das Aufbringen ist bereits enthalten.</p>`:''}${d.type==='Rechnung'?`<p>Zahlbar innerhalb von ${Number(s.paymentDays)} Tagen ab Rechnungsdatum.${s.iban?'<br>IBAN: '+esc(s.iban)+' · '+esc(s.bank):''}</p>`:''}${d.type==='Bestellübersicht'?'<p>Interne Grundlage für die separate Bestellung bei HAKRO. Es wurde keine Bestellung ausgelöst.</p>':''}${internal?`<h3>Werkstatthinweise</h3><pre>${esc(o.notes||'Keine zusätzlichen Hinweise.')}</pre>`:''}${['Angebot','Werkstattzettel'].includes(d.type)?placementPages(o)+(typeof standaloneTransferPages==='function'?standaloneTransferPages(o):''):''}<hr><pre>${esc(s.footer)}</pre>${d.type==='Rechnung'?'<p style="font-size:11px">Ausgabe als Papier/PDF. Keine strukturierte E-Rechnung.</p>':''}</article>`;}
function missingPrint(o){return o.lines.filter(l=>!l.salesGenerated&&Number(l.transfersPerItem)>0&&!o.transferJobs?.some(j=>j.lineId===l.id));}
function validateDocument(d){if(d.order.salesVersion===2&&d.order.placements.some(p=>!p.lineId||!d.order.lines.some(l=>l.id===p.lineId)))throw Error('Motiv zuerst einer Textilposition zuordnen.');if(d.order.salesVersion===2&&['Angebot','Rechnung'].includes(d.type)&&missingPrint(d.order).length&&!(d.type==='Angebot'&&d.pendingPrint?.length))throw Error('Transferdruck fehlt: Für veredelte Textilien zuerst Motiv und Druckmaße zuordnen.');if(!d.customer.name||!d.customer.address.trim())throw Error('Kunde und vollständige Rechnungsanschrift fehlen.');if(!d.order.lines.length)throw Error('Mindestens eine Position erforderlich.');if(!d.supplier.company.trim()||!d.supplier.address.trim())throw Error('Zuerst Absender und Anschrift unter Einstellungen ausfüllen.');if(['Angebot','Rechnung'].includes(d.type))Core.total(d.order.lines);if(d.type==='Rechnung'){if(!d.supplier.taxid.trim())throw Error('Steuernummer oder USt-IdNr. des Absenders fehlt.');if(!d.order.serviceDate)throw Error('Liefer-/Leistungsdatum fehlt.');}}
function createDocument(type){const o=order(),c=customer(o.customerId);if(!c)throw Error('Bitte zuerst Kunde auswählen und Auftragsdaten speichern.');const d=makeDocument(type,o,c);if(type==='Angebot'&&d.order.salesVersion===2){const open=missingPrint(d.order);if(open.length){if(!confirm(`Für ${open.length} Textilposition(en) ist noch kein Motiv zugeordnet:\n${open.map(l=>'· '+l.description).join('\n')}\n\nDas Angebot enthält dann Textilien und Aufbringen, aber noch keinen Transferdruck. Auf dem Angebot steht der Hinweis, dass der Druckpreis nach Motivfreigabe folgt. Fortfahren?`))return;d.pendingPrint=open.map(l=>[l.description,l.color&&'Farbe '+l.color,l.size&&'Größe '+l.size].filter(Boolean).join(' · '));}}if(['Angebot','Rechnung'].includes(type)){Core.total(o.lines);validateDocument(d);}previewDocument(d,true);}
function previewDocument(d,isNew=false){modal({title:'Dokumentvorschau',body:`<div class="row">${button('printDoc','Drucken / als PDF speichern','primary')}${isNew?button('freezeDoc','Dokumentstand speichern'):''}${!isNew&&d.type==='Rechnung'?button('cancelDoc','Stornodokument erzeugen','danger'):''}</div><p class="sub">Gespeicherte Dokumentstände werden durch spätere Auftragsänderungen nicht verändert. Dies ersetzt noch kein revisionssicheres Archiv.</p><div id="documentPreview">${docHTML(d)}</div>`},()=>{bind('#printDoc','click',async()=>{const html=docHTML(d);$('#printArea').innerHTML=html;$('#modal').close();const imgs=Array.from($('#printArea').querySelectorAll('img'));await Promise.all(imgs.map(im=>im.decode().catch(()=>{})));document.title=`${d.type}_${d.number}`;window.print();});bind('#freezeDoc','click',async()=>{validateDocument(d);if(d.type==='Rechnung'&&state.docs.some(x=>x.type==='Rechnung'&&x.order.id===d.order.id&&!state.docs.some(z=>z.original===x.number)))throw Error('Für diesen Auftrag besteht bereits eine Rechnung. Zuerst prüfen oder stornieren.');if(!confirm('Dokumentstand mit eigener Nummer speichern? Inhalt bleibt anschließend unverändert.'))return;const num=nextNumber(d.type,d.date);if(state.docs.some(x=>x.number===num.number))throw Error('Nummer bereits vergeben. Nummernkreis prüfen.');await num.commit();d.number=num.number;d.frozen=true;state.docs.push(d);await save();$('#modal').close();previewDocument(d);});bind('#cancelDoc','click',async()=>{if(state.docs.some(x=>x.original===d.number))throw Error('Rechnung wurde bereits storniert.');if(!confirm('Unveränderliches Stornodokument zur gesamten Rechnung anlegen?'))return;const st=structuredClone(d);st.id=uid();st.type='Storno';st.original=d.number;st.date=date();const num=nextNumber('Storno',st.date);if(state.docs.some(x=>x.number===num.number))throw Error('Nummer bereits vergeben. Nummernkreis prüfen.');await num.commit();st.number=num.number;st.frozen=true;state.docs.push(st);await save();$('#modal').close();previewDocument(st);});});}
function documentsPage(){$('#app').innerHTML=`<h1>Dokumente</h1><section class="card"><p>Unveränderte Momentaufnahmen mit eigenem Nummernkreis. Keine automatische Übermittlung an Kunden oder Lieferanten.</p><div class="tablewrap"><table><thead><tr><th>Nummer</th><th>Typ</th><th>Kunde</th><th>Datum</th><th></th></tr></thead><tbody>${state.docs.slice().reverse().map(d=>`<tr><td>${esc(d.number)}</td><td>${esc(d.type)}</td><td>${esc(d.customer.name)}</td><td>${esc(d.date)}</td><td><button data-open-doc="${d.id}">Öffnen</button></td></tr>`).join('')}</tbody></table></div></section>`;document.querySelectorAll('[data-open-doc]').forEach(b=>b.onclick=()=>previewDocument(state.docs.find(d=>d.id===b.dataset.openDoc)));}
function settingsPage(){const s=state.settings;$('#app').innerHTML=`<h1>Einstellungen und Datensicherung</h1><section class="card"><h2>Absender für Kundendokumente</h2><form id="settingsForm"><div class="grid">${input('company','Vollständiger Unternehmensname',s.company,'text','required')}${input('taxid','Steuernummer oder USt-IdNr.',s.taxid)}${input('email','E-Mail',s.email,'email')}${input('prefix','Nummernkreis-Präfix',s.prefix,'text','required pattern="[A-Za-z0-9-]{1,12}"')}${input('iban','IBAN',s.iban)}${input('bank','Bank',s.bank)}${input('paymentDays','Zahlungsziel in Tagen',s.paymentDays,'number','min="0" max="365" required')}</div>${textfield('address','Vollständige Anschrift',s.address)}${textfield('footer','Dokumentfuß: weitere Unternehmensangaben',s.footer)}<button class="primary">Einstellungen speichern</button></form></section><section class="card"><h2>Dieses Gerät</h2><p>Gerätekennung: <strong>${esc(deviceInfo.code||'noch nicht festgelegt')}</strong>. Neue Nummern auf diesem Gerät: ${esc(state.settings.prefix)}-${esc(deviceInfo.code||'?')}-RE-${date().slice(0,4)}-00001 usw.</p>${button('changeDevice','Gerätekennung ändern')}<p class="sub">Jede Kennung nur an einem Gerät verwenden. Ändern nur, wenn die neue Kennung sonst nirgends benutzt wird.</p><p>Dauerhafter Speicher: <strong>${storagePersisted===true?'vom Browser zugesagt':storagePersisted===false?'nicht zugesagt':'wird von diesem Browser nicht gemeldet'}</strong>${storagePersisted===true?'':'. Der Browser darf die lokalen Daten bei Speichermangel löschen. Regelmäßig sichern. Als App installieren oder als Lesezeichen speichern erhöht die Chance auf die Zusage.'}</p></section><section class="card"><h2>Manueller Gerätewechsel</h2><ol><li>Auf dem bisherigen Gerät Sicherung / Übergabe exportieren.</li><li>Die verschlüsselte RTX-Datei auf das andere Gerät übertragen.</li><li>Dort die Datei öffnen und das Passwort eingeben.</li><li>Nur auf diesem Gerät weiterarbeiten. Vor einem Wechsel wieder exportieren.</li><li>Die Sicherung enthält alle Motivbilder. Sicherungen älterer Versionen lassen sich weiter öffnen.</li></ol><div class="notice">Es gibt keine Zusammenführung paralleler Bearbeitungen. Der Import ersetzt den gesamten Arbeitsbereich. Gleiche Revisionsnummern erkennen nicht jeden Konflikt; deshalb nur eine aktive Arbeitskopie verwenden.</div><label>Projektdatei öffnen<input id="restoreFile" type="file" accept=".rtx,application/json"></label>${button('backupSettings','Verschlüsselte Sicherung speichern','primary')}<p class="sub">Ablage: verschlüsselt im Browserprofil. Beim Löschen der Browserdaten geht die lokale Kopie verloren. Passwort und Sicherung getrennt sicher verwahren. Automatische Sperre nach 10 Minuten Inaktivität.</p></section><section class="card"><h2>Stand der Pilotversion</h2><p>Unterstützt: Kunden, Aufträge, Variantenstaffeln, manuelle Preise, HAKRO-XLSX-Import, PNG/JPG/WebP-Platzierung, Dokumentvorschau, eingefrorene Dokumentstände, Storno, Druckdialog und verschlüsselte Sicherung.</p><p>Noch offen: native EXE/APK, strukturierte E-Rechnung, revisionssicheres Archiv, Rollen, automatische Löschfristen, SVG/PDF-Motivimport, eigene Textilvorlagen, maßkalibrierte Vorschau, DTF-Sheet-Editor, Lieferanten-Importprofile und Bestellung aus beliebigen Kunden-Excel-Tabellen.</p><p>7 % und 19 % werden manuell ausgewählt. Die App bestätigt nicht die steuerliche Zulässigkeit des gewählten Satzes.</p></section>`;bind('#settingsForm','submit',async e=>{e.preventDefault();const f=formData(e.target);if(state.docs.length&&f.prefix!==s.prefix)throw Error('Nummernkreis ist nach dem ersten Dokument in dieser Pilotversion gesperrt.');Object.assign(s,f,{paymentDays:Number(f.paymentDays)});await save();delete e.target.dataset.dirty;toast('Einstellungen gespeichert.');});bind('#restoreFile','change',e=>restore(e.target.files[0]));bind('#backupSettings','click',backup);bind('#changeDevice','click',deviceDialog);}
const active=()=>{lastActivity=Date.now();lockWarned=false;};for(const ev of ['pointerdown','keydown'])document.addEventListener(ev,active);document.addEventListener('input',e=>{active();const f=e.target?.form||e.target?.closest?.('form');if(f)f.dataset.dirty='1';});
setInterval(()=>{if(!state||saving||storageError)return;const idle=Date.now()-lastActivity;if(idle>600000)lock(true).catch(fail);else if(idle>540000&&!lockWarned){lockWarned=true;toast('Seit 9 Minuten keine Eingabe. In 1 Minute wird gesperrt. Nicht gespeicherte Eingaben werden verschlüsselt aufbewahrt.');}},15000);
window.addEventListener('error',e=>{if(e.error)fail(e.error);});window.addEventListener('unhandledrejection',e=>fail(e.reason||Error('Unbekannter Fehler')));window.addEventListener('beforeunload',e=>{if(saving||storageError){e.preventDefault();e.returnValue='Änderungen noch nicht gespeichert.';}});
(async()=>{try{if(!crypto.subtle)throw Error('Dieser Browser stellt hier keine lokale Verschlüsselung bereit. Datei in einem aktuellen Desktop-Browser oder über einen lokalen Server öffnen.');db=await openDB();await gate();}catch(e){$('#app').innerHTML=`<section class="card"><h1>Start nicht möglich</h1><p>${esc(e.message)}</p><p>Keinen unverschlüsselten Ersatzspeicher verwenden. Siehe START.html im Paket.</p></section>`;}})();
